def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    m = g != bg

    def has_nb(y, x, d):
        # d=+1: down-right orientation, d=-1: down-left orientation
        for dy, dx in ((1, d), (-1, -d)):
            yy, xx = y + dy, x + dx
            if 0 <= yy < H and 0 <= xx < W and m[yy, xx]:
                return True
        return False

    dr, dl = [], []
    for y in range(H):
        for x in range(W):
            if m[y, x]:
                if has_nb(y, x, 1):
                    dr.append((y, x))
                elif has_nb(y, x, -1):
                    dl.append((y, x))

    out = g.copy()
    # majority orientation (by cell count) -> 8, minority -> 2
    if len(dr) >= len(dl):
        major, minor = dr, dl
    else:
        major, minor = dl, dr

    for (y, x) in major:
        out[y, x] = 8
    emit(out, "Recolour the diagonal family with more cells to 8")
    for (y, x) in minor:
        out[y, x] = 2
    emit(out, "Recolour the diagonal family with fewer cells to 2")
    return out
